'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=0)=>x==null?'—':Number(x).toLocaleString('es-ES',{maximumFractionDigits:d});
const date=s=>s?new Date(s.slice(0,10)+'T12:00:00').toLocaleDateString('es-ES'):'Sin fecha';
let APISTATUS={},S,REV,AUTH,DASH,view='overview',entity='',program='',query='',proposal,explains=[],calcs=[];
const names={overview:'Resumen',plans:'Planes y cumplimiento',deadlines:'Fechas límite',consortium:'Agrupación',courses:'Cursos',people:'Alumnos',planning:'Planificación',team:'Equipo y tareas',affinity:'Siguiente curso',rules:'Reglas y simulador',sources:'Fuentes e incidencias',settings:'Configuración',integrations:'Conexiones API'};
const ccaa=['Andalucía','Aragón','Principado de Asturias','Illes Balears','Canarias','Cantabria','Castilla y León','Castilla-La Mancha','Cataluña','Comunitat Valenciana','Extremadura','Galicia','Comunidad de Madrid','Región de Murcia','Comunidad Foral de Navarra','País Vasco','La Rioja','Ceuta','Melilla'];
async function api(path,body){let r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':AUTH.csrf}:{},body:body?JSON.stringify(body):undefined});let x=await r.json();if(!r.ok){if(r.status===401&&path!=='login'){AUTH=await api('bootstrap');login();}throw Error(x.error||'Error de conexión');}return x;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function dialog(html){$('#detail-body').innerHTML=html;$('#detail').showModal();}
$('#close-dialog').onclick=()=>$('#detail').close();
const badge=(s,kind='')=>`<span class="badge ${kind}">${esc(s)}</span>`;
const button=(s,act,id='',cls='')=>`<button class="${cls}" data-act="${act}" data-id="${esc(id)}">${esc(s)}</button>`;
const opts=(list,key='id',label='name',val='')=>list.map(x=>`<option value="${esc(x[key])}" ${x[key]===val?'selected':''}>${esc(x[label])}</option>`).join('');
const select=(name,label,list,val='',required=true)=>`<label>${esc(label)}<select name="${name}" ${required?'required':''}>${list.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const source=(id,loc='')=>{let s=S.sources.find(x=>x.id===id);return s?`<a href="/api/source/${encodeURIComponent(id)}${loc.match(/^p\. (\d+)/)?'#page='+loc.match(/^p\. (\d+)/)[1]:''}" target="_blank" rel="noopener">${esc(s.name)}</a> · ${esc(loc)}`:esc(id+' · '+loc);};
const cname=id=>S.courses.find(c=>c.id===id)?.title||id;
const mname=id=>S.managers.find(m=>m.id===id)?.name||id;
const ename=id=>S.entities.find(e=>e.id===id)?.name||id;
function filtered(){return S.courses.filter(c=>(!entity||c.entity===entity)&&(!program||c.program===program)&&(!query||(c.title+' '+c.code).toLowerCase().includes(query.toLowerCase())));}
function evidence(m){let i=explains.push(m)-1;return button('Ver cálculo y fuente','explain',i,'link mini');}
function calc(x){let i=calcs.push(x)-1;return button('Ver cálculo y fuente','calc',i,'link mini');}
function metric(m){return `<div class="card"><div class="muted">${esc(m.label)}</div><div class="number">${num(m.value,1)}${m.value!=null&&m.unit==='%'?' <small>%</small>':''}</div><div class="hint">${badge(m.status,m.status==='verificado'?'good':'warn')} ${evidence(m)}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">No hay registros para esta selección.</td></tr>`}</tbody></table></div>`;}
async function refresh(){let [s,d,status]=await Promise.all([api('state'),api('dashboard'),api('integrations/status')]);APISTATUS=status;S=s.state;REV=s.revision;DASH=d;render();}
function login(){ $('#root').innerHTML=`<div class="login"><form id="login" class="login-box"><div class="eyebrow">AKACENTER · JUAN PABLO</div><h1>SEPE Control</h1><p class="subtle">Una vista común para coordinar los planes, el equipo y cada oportunidad de formación.</p>${field('username','Usuario','','text','required autocomplete="username"')}${field('password','Contraseña','','password','required autocomplete="current-password"')}<button class="primary" type="submit">Entrar</button><p id="login-error" role="alert"></p><p class="mini muted">Acceso individual. Las cuentas las crea el administrador durante la instalación.</p></form></div>`;}
function render(){explains=[];calcs=[];$('#root').innerHTML=`<div class="shell"><aside><div class="brand">SEPE Control<small>AKACENTER + JUAN PABLO</small></div><nav>${Object.entries(names).map(([k,v])=>button(v,'nav',k,k===view?'active':'')).join('')}</nav><div class="aside-foot">Segunda ventana · 2025<br>Programación importada ${date(S.as_of)}<br><br>${esc(AUTH.user)} · ${esc(AUTH.role)}<br>${button('Cambiar contraseña','password','','link')}${button('Cerrar sesión','logout','','link')}</div></aside><main class="main"><div class="topbar"><div class="eyebrow">CONTROL DE FORMACIÓN</div><div>${badge(APISTATUS.enabled?'APIs habilitadas':'APIs desactivadas',APISTATUS.enabled?'good':'warn')} ${button('Actualizar','refresh')}</div></div><div class="heading"><h1>${names[view]}</h1><p class="subtle">${({overview:'Visibilidad compartida, decisiones con evidencia.',plans:'Cada expediente tiene sus propios compromisos.',deadlines:'Fecha original, confirmación e impacto en el calendario.',consortium:'Resultados de todos los socios con origen y corte identificados.',courses:'Programación, plazas y contraste con la resolución.',people:'La matrícula y la finalización son estados distintos.',planning:'Fechas, necesidades de captación y margen de ejecución.',team:'Una persona responsable por alumno y una carga equilibrada.',affinity:'Continuidad formativa entre cursos, planes y entidades.',rules:'Reglas verificadas y supuestos de cálculo visibles.',sources:'El origen de los datos, siempre accesible.',settings:'Parámetros operativos.',integrations:'Consultar, conciliar y aplicar los datos de las dos APIs.'})[view]}</p></div><div class="filters"><label>Entidad<select id="entity"><option value="">Ambas entidades</option>${opts(S.entities,'id','name',entity)}</select></label><label>Expediente<select id="program"><option value="">Todos los expedientes</option>${S.programs.map(p=>`<option value="${p.id}" ${program===p.id?'selected':''}>${p.id} · ${esc(p.name)}</option>`).join('')}</select></label>${view==='courses'?`<label>Buscar curso<input id="search" value="${esc(query)}" placeholder="Título o código"></label>`:''}</div><div id="content"></div></main></div>`;
const f={overview:overview,plans:plans,deadlines:deadlines,consortium:consortiumView,courses:courses,people:people,planning:planning,team:team,affinity:affinity,rules:rules,sources:sources,settings:settings,integrations:integrationsView};f[view]();}
function overview(){let cs=filtered(),ids=new Set(cs.map(c=>c.id)),as=S.allocations.filter(a=>(!entity||a.entity===entity)&&(!program||a.program===program));let target=cs.reduce((a,c)=>a+c.target,0),en=S.enrollments.filter(e=>ids.has(e.course)),finals=en.filter(e=>e.state==='finalizado'&&e.validated);$('#content').innerHTML=`<div class="banner"><strong>${en.length?'Seguimiento de alumnos.':'Datos de alumnos pendientes.'}</strong> ${en.length?`${en.length} matrículas registradas en esta selección.`:'Todavía no hay matrículas individuales cargadas.'} Los recuentos de las hojas se conservan como observaciones. No acreditan certificación ni cobertura de los socios de la agrupación.</div><div class="cards"><div class="card"><div class="muted">Expedientes / bloques de entidad</div><div class="number">${new Set(cs.map(c=>c.program)).size} <small>/ ${as.length}</small></div>${calc({formula:'Expedientes distintos por identificador / combinaciones entidad + expediente.',sources:as.map(a=>({source:a.source,locator:'PLANES!B'+a.source_row})),value:as.length})}</div><div class="card"><div class="muted">Participaciones programadas</div><div class="number">${num(target)}</div><div class="hint">${cs.length} filas de cursos. No son personas únicas.</div>${calc({formula:'Σ columna G de PLANES, respetando los desgloses por sede.',value:target,sources:cs.map(c=>({source:c.source,locator:'PLANES!G'+c.source_row}))})}</div><div class="card"><div class="muted">Finalizados validados</div><div class="number">${en.length?num(finals.length):'—'}</div><div class="hint">${en.length?'Con evidencia de validación':'Sin datos individuales'}</div>${calc({formula:'Contar matrículas con state=finalizado y validated=true. Anulados y sustituidos excluidos.',value:en.length?finals.length:null,records:finals.map(e=>e.id),sources:finals.map(e=>({source:e.source,locator:e.updated_at}))})}</div><div class="card"><div class="muted">Incidencias documentales</div><div class="number">${S.issues.filter(i=>as.some(a=>a.id===i.scope)).length}</div><div class="hint">Fechas, códigos, horas y objetivos</div>${button('Revisar fuentes','nav','sources','link')}</div></div><div class="panel"><h2>Prioridades de la semana</h2><div class="grid2"><div><h3>1. Resolver la base documental</h3><p>Confirmar las fechas de Metal y Servicios a empresas y corregir las discrepancias de las acciones. Solicitar a la agrupación los datos del resto de entidades.</p><h3>2. Captar según el déficit real</h3><p>Priorizar los cursos próximos y las CCAA menos representadas. El límite del 30 % de desempleo se calcula sobre participantes certificados; no es un mínimo que haya que alcanzar.</p></div><div><h3>3. Proteger las finalizaciones</h3><p>Asignar seguimiento desde el inicio. Registrar asistencia o controles de aprendizaje, incidencias y evidencia de cierre antes de marcar validado.</p><h3>4. Proponer continuidad</h3><p>Ofrecer el siguiente curso por afinidad, acceso y calendario, revisando el cupo del expediente de destino.</p></div></div></div><div class="panel"><h2>Situación por entidad y plan</h2>${allocationTable(as)}</div>`;}
function allocationTable(as){return table(['Entidad / plan','Objetivo local','Finalizados','Ejecución','Fecha límite','Detalle'],as.map(a=>{let d=DASH.allocations[a.id];return [`<strong>${ename(a.entity)}</strong><br>${esc(a.name)}<div class="mini muted">${a.program}</div>`,num(d.target),num(d.finalized),d.metrics[0].value==null?'Sin datos':num(d.metrics[0].value,1)+' %',date(a.deadline)+'<br>'+badge(a.deadline_status,a.deadline_status==='revisar'?'bad':'warn'),button('Abrir','allocation',a.id)];}));}
function plans(){let as=S.allocations.filter(a=>(!entity||a.entity===entity)&&(!program||a.program===program));$('#content').innerHTML=`<div class="banner">Los controles legales se realizan por expediente completo. Los bloques de Akacenter y Juan Pablo muestran su ejecución operativa. Su suma puede seguir sin incluir a todos los socios.</div><div class="panel">${allocationTable(as)}</div><div class="panel"><h2>Compromisos de valoración territorial</h2>${table(['Expediente','Puntos A.2 aprobados','CCAA para conservar A.2','Fuente'],S.programs.filter(p=>!program||p.id===program).map(p=>[p.id+'<br>'+esc(p.name),num(p.vt.a2),p.vt.a2>=20?'10 con ≥ 5 % cada una':'6 con ≥ 5 % cada una',source(p.id,'p. 3')+'<br>'+source('anexo_vi','A.2')]))}</div>`;}
function allocationDetail(id){let a=S.allocations.find(x=>x.id===id),p=S.programs.find(x=>x.id===a.program),d=DASH.allocations[id],g=DASH.programs[a.program];dialog(`<div class="eyebrow">${ename(a.entity)} · ${p.id}</div><h2>${esc(a.name)}</h2><p>${esc(g.coverage_note)}</p><div class="cards">${d.metrics.slice(0,2).map(metric).join('')}</div>${g.alerts.map(a=>`<div class="banner">${esc(a.message)}. ${badge('Cobertura parcial','warn')}</div>`).join('')}<h3>Certificados disponibles del expediente</h3><p class="subtle">Se combinan los bloques disponibles de ambas entidades. Cobertura parcial; no es una declaración de cumplimiento.</p><div class="cards">${g.metrics.slice(2).map(metric).join('')}</div><div class="grid2"><div class="panel"><h3>Margen de desempleo</h3><p>${num(g.unemployed)} desempleados entre ${num(g.certified)} certificados.</p><p>Si todos los demás datos permanecen iguales: hasta <strong>${num(g.unemployed_headroom)}</strong> desempleados adicionales; o <strong>${num(g.occupied_needed)}</strong> nuevos ocupados para corregir un exceso.</p>${calc({formula:'Margen=floor((0,30×N−D)/0,70), mínimo 0. Ocupados necesarios=max(0,ceil(D/0,30−N)). Cada nueva incorporación aumenta el denominador. Sin N o con situación laboral desconocida: no calculable. Es un escenario de la muestra disponible, no autorización de admisión.',value:g.unemployed_headroom,sources:[{source:'convocatoria',locator:'art. 5.1.f y 5.2'}],records:g.metrics[2].record_ids})}<p>Sector propio: ${g.own_sector} · Otro sector: ${g.other_sector} · Desconocido: ${num(g.sector_unknown)}.</p><p class="mini">${esc(p.other_sector_source)}</p></div><div class="panel"><h3>Distribución por domicilio</h3><p>Umbral actual: ${g.certified?g.geo_threshold:'—'} por CCAA. Puntos A.2 observados: ${g.certified?g.geo_points:'—'}; compromiso: ${p.vt.a2}.</p>${table(['CCAA','Certificados','Hasta el 5 % actual'],Object.entries(g.geo).map(([k,v])=>[esc(k),num(v),num(Math.max(0,g.geo_threshold-v))]))}<p class="mini">El déficit mostrado mantiene fijo el total actual. Añadir alumnos modifica el denominador y obliga a recalcular todas las CCAA.</p>${source('anexo_vi','A.2')}</div></div><h3>Fecha límite</h3><p>${date(a.deadline)} · ${esc(a.deadline_note)}</p><p>${source(a.deadline_source,a.deadline_cell)}</p>${AUTH.role==='admin'?button('Registrar fecha confirmada','deadline',a.id):''}<h3>Observaciones de las hojas auxiliares</h3>${d.started_observation==null?'<p>Sin recuentos auxiliares.</p>':`<p>${d.started_observation} iniciados anotados. No se agregan a las matrículas individuales.</p>`}`);}
function courses(){let cs=filtered();$('#content').innerHTML=`<div class="toolbar"><p>${cs.length} filas de programación · se preservan las sedes distintas.</p><a class="button" href="/api/courses.csv">Exportar catálogo CSV</a></div><div class="panel">${table(['Curso / acción','Entidad / plan','Plazas / horas','Calendario','Contraste',''],cs.map(c=>[`<strong>${esc(c.title)}</strong><div class="mini">${esc(c.code)} · acción ${c.action} · ${c.mode}</div>`,ename(c.entity)+'<br>'+c.program,`${c.target} / ${c.hours} h`,date(c.start)+'<br>'+date(c.end),badge(c.comparison_status==='revisar'?'Revisar':'Coincidencia parcial',c.comparison_status==='revisar'?'bad':'warn'),button('Detalle','course',c.id)]))}</div>`;}
function courseDetail(id){let c=S.courses.find(x=>x.id===id),r=c.resolution_match,es=S.enrollments.filter(e=>e.course===id);dialog(`<div class="eyebrow">${ename(c.entity)} · ${c.program} · ACCIÓN ${c.action}</div><h2>${esc(c.title)}</h2><p>${esc(c.code)} · ${c.hours} horas · ${c.mode} · ${esc(c.location)}</p><p>${c.target} participaciones programadas. ${date(c.start)} → ${date(c.end)}.</p><p>Horario: ${esc(c.schedule||'pendiente')} · Nivel: ${esc(c.level||'pendiente')}</p><h3>Fuente de programación</h3><p>${source(c.source,c.source_locator)}</p><h3>Contraste con la resolución</h3>${r?`<p>Acción ${r.action} · ${esc(r.code)} · ${r.hours} horas · ${r.target} participantes admitidos en la tabla de la acción.</p><p>${source(c.program,'p. '+r.page)}</p>`:'<p>Sin correspondencia concluyente.</p>'}<p>${esc(c.resolution_evidence)}</p>${c.comparison_notes.map(x=>`<div class="banner">${esc(x)}</div>`).join('')}<p class="mini">Una coincidencia parcial comprueba los campos extraídos. Falta conciliar el reparto completo por entidad, centro y posibles modificaciones posteriores.</p><h3>Seguimiento</h3><p>${es.length} matrículas individuales · ${es.filter(e=>e.state==='finalizado'&&e.validated).length} finalizados validados.</p>${S.snapshots.filter(x=>x.course===id).map(x=>`<div class="panel">${Object.entries(x.fields).map(([k,v])=>`<p>${esc(k)}: ${v.value} · ${source(x.source,v.cell)}</p>`).join('')}<p>${esc(x.note)}</p></div>`).join('')}${button('Registrar matrícula','enrollment',id)} ${button('Siguientes cursos','rec-origin',id)}`);}
function people(){let ids=new Set(filtered().map(c=>c.id));let es=S.enrollments.filter(e=>ids.has(e.course));$('#content').innerHTML=`<div class="toolbar">${button('Nueva matrícula','enrollment')}${AUTH.role==='admin'?button('Importar JSON','import'):''}</div><div class="banner">Usa un identificador interno seudonimizado. Situación laboral y sector corresponden al inicio de la acción; la certificación exige validación documental.</div><div class="panel">${table(['Alumno / matrícula','Curso','Estado','Situación al inicio','Certificación',''],es.map(e=>[esc(e.name||e.person)+'<div class="mini">'+esc(e.person)+' · '+esc(e.id)+'</div>',esc(cname(e.course)),badge(e.state),esc(e.employment)+'<br>'+esc(e.ccaa),e.certified_valid&&e.validated?'Validada':'Pendiente',button('Editar','edit-enrollment',e.id)+(e.integration?button('Ver origen','api-provenance',e.id):'')]))}</div>`;}
function enrollmentForm(course='',id=''){let e=S.enrollments.find(x=>x.id===id)||{course,employment:'desconocido',sector_relation:'desconocido',state:'matriculado'};dialog(`<h2>${id?'Editar':'Registrar'} matrícula</h2><form id="enrollment" class="form-grid"><input type="hidden" name="id" value="${esc(id)}">${field('person','ID interno del alumno',e.person,'text','required maxlength="100"')}<label>Curso<select name="course" required>${S.courses.map(c=>`<option value="${c.id}" ${c.id===e.course?'selected':''}>${ename(c.entity)} · ${c.code} · ${c.title} · ${c.location}</option>`).join('')}</select></label>${select('state','Estado',['matriculado','iniciado','finalizado','abandono','anulado','sustituido'],e.state)}${select('employment','Situación laboral al inicio',['desconocido','ocupado','desempleado','autonomo','erte'],e.employment)}${select('sector_relation','Sector de la empresa',['desconocido','propio','otro','no_aplica'],e.sector_relation)}<label>CCAA de domicilio<select name="ccaa"><option value="">Desconocida</option>${ccaa.map(x=>`<option ${x===e.ccaa?'selected':''}>${esc(x)}</option>`).join('')}</select></label>${field('company','ID empresa (para concentración)',e.company)}${select('priority','Colectivo prioritario',['Desconocido','Sí','No'],e.priority==null?'Desconocido':e.priority?'Sí':'No')}${field('progress','% asistencia / controles (si consta)',e.progress,'number','min="0" max="100" step="0.01"')}<label class="check"><input name="validated" type="checkbox" ${e.validated?'checked':''}> Resultado validado</label><label class="check"><input name="certified_valid" type="checkbox" ${e.certified_valid?'checked':''}> Participación certificada válida</label><label class="full">Evidencia del resultado y observaciones<textarea name="evidence" maxlength="3000">${esc(e.evidence)}</textarea></label><p class="full mini">${e.integration?'Datos importados de APIs. Las correcciones manuales requieren evidencia y se revisarán si cambia el origen. ':''}Marcar validado requiere indicar evidencia. Un abandono financiable no se convierte por ello en un finalizado. La aplicación no certifica automáticamente asistencia ni aprendizaje.</p><button class="primary" type="submit">Guardar matrícula</button></form>`);}
async function planning(){ $('#content').innerHTML='<p>Cargando propuesta…</p>';try{proposal=await api('planning');if(view==='planning')drawPlanning();}catch(e){toast(e.message);}}
function drawPlanning(){let allowed=new Set(filtered().map(c=>c.id)),ps=proposal.proposals.filter(p=>allowed.has(p.course)),bs=proposal.blocked.filter(p=>allowed.has(p.course));$('#content').innerHTML=`<div class="banner">Propuesta orientativa con ${Math.round(S.settings.completion*100)} % de finalización y ${Math.round(S.settings.conversion*100)} % de conversión. Las fechas de programación siguen pendientes de contrastar con las notificaciones, salvo confirmación registrada.</div><div class="cards">${proposal.loads.map(l=>`<div class="card"><div>${esc(mname(l.manager))}</div><div class="number">${num(l.hours,1)} <small>h</small></div><p class="hint">${num(l.weeks,1)} semanas a ${l.weekly_capacity} h/sem.</p>${calc({formula:'Carga = suma de horas de tareas abiertas + horas estimadas de propuestas aún no guardadas. Semanas=carga/capacidad semanal. Vista global de ambas entidades.',value:l.hours,sources:[{source:'Modelo interno de planificación',locator:'settings y tareas abiertas'}]})}</div>`).join('')}</div><div class="panel"><div class="toolbar"><h2>${ps.length} propuestas / ${bs.length} bloqueos</h2>${AUTH.role!=='lector'?button('Guardar borradores y tareas confirmadas','apply-plan','','primary'):''}</div><p class="mini">${esc(proposal.method)} Guardar afecta a ambos centros y todos los planes. Los campos calculados son hipótesis; no se cambia el Excel de origen. Los plazos provisionales guardan borradores, sin generar tareas de captación.</p>${table(['Curso','Gestor','Inicio → fin','Necesidad estimada','Carga',''],ps.map(p=>[esc(cname(p.course))+'<div class="mini">'+p.allocation+'</div>',esc(mname(p.manager)),date(p.start)+' → '+date(p.end),`${p.enrollments} matrículas · ${p.contacts} contactos<br>${p.cohorts} grupos orientativos`,num(p.hours,1)+' h '+badge(p.deadline_status,p.deadline_status==='confirmada'?'good':'warn')+' '+(p.capacity_warning?badge('Capacidad insuficiente','bad'):''),calc({formula:p.formula,value:{matriculas:p.enrollments,contactos:p.contacts,horas:p.hours,inicio:p.start,fin:p.end},sources:[{source:p.source,locator:p.locator},{source:'Parámetros internos',locator:JSON.stringify(proposal.assumptions)}]})]))}</div><div class="panel"><h2>Cursos que requieren intervención</h2>${table(['Curso','Motivo'],bs.map(x=>[esc(cname(x.course)),esc(x.reason)]))}</div>${S.groups.length?`<div class="panel"><h2>Calendario guardado (${S.groups.length})</h2>${table(['Curso','Inicio','Fin','Responsable',''],S.groups.filter(g=>allowed.has(g.course)).map(g=>[esc(cname(g.course)),date(g.start),date(g.end),esc(mname(g.owner))+' '+(g.planning_hold?badge('Revisar plazo','warn'):''),button('Ajustar','group',g.id)]))}</div>`:''}`;}
function team(){let loads=S.managers.map(m=>({...m,tasks:S.tasks.filter(t=>t.owner===m.id&&t.status!=='hecha')}));$('#content').innerHTML=`<div class="banner green"><strong>Cartera común, responsabilidad individual.</strong> Cada alumno puede tener una sola tarea abierta de contacto. El responsable coordina captación y seguimiento; las especialidades de los gestores son orientativas, no silos por empresa.</div><div class="cards">${loads.map(m=>`<div class="card"><h3>${esc(m.name)}</h3><p>${esc(m.focus)}</p><div class="number">${num(m.tasks.reduce((a,t)=>a+t.hours,0),1)} <small>h pendientes</small></div><p>${m.weekly_hours} h/semana disponibles</p>${AUTH.role==='admin'?button('Capacidad y nombre','manager',m.id):''}</div>`).join('')}</div><div class="panel"><div class="toolbar"><h2>Tareas del equipo</h2>${AUTH.role!=='lector'?button('Nueva tarea','task','','primary'):''}</div>${table(['Tarea / alumno','Responsable','Vence','Horas','Estado',''],S.tasks.filter(t=>!t.course||filtered().some(c=>c.id===t.course)).map(t=>[esc(t.title)+(t.person?'<br>'+esc(t.person):''),esc(mname(t.owner)),date(t.due),num(t.hours,1),badge(t.status)+(t.planning_hold?badge('Plazo pendiente','warn'):''),button('Editar','task',t.id)]))}</div><div class="panel"><h2>Rutina de coordinación propuesta</h2><p>Lunes: revisar déficits, fechas y capacidad. Diario: atender próximos inicios y alumnos con incidencias. Miércoles: revisar CCAA, sector y desempleo con datos actualizados. Viernes: cerrar evidencias de finalización y proponer continuidad.</p><p>Reservar tiempo de seguimiento antes de comprometer nuevas matrículas. Ajustar las tasas después de dos semanas y redistribuir tareas por horas pendientes, no por número bruto de cursos.</p></div>`;}
function taskForm(id=''){let t=S.tasks.find(x=>x.id===id)||{owner:AUTH.manager||'g1',hours:1,due:new Date().toISOString().slice(0,10),status:'pendiente'};dialog(`<h2>Tarea de captación o seguimiento</h2><form id="task" class="form-grid"><input name="id" type="hidden" value="${esc(id)}">${field('title','Tarea',t.title,'text','required')}<label>Responsable<select name="owner">${opts(S.managers,'id','name',t.owner)}</select></label>${field('person','ID alumno (opcional)',t.person)}<label>Curso<select name="course"><option value="">General</option>${opts(S.courses,'id','title',t.course)}</select></label>${field('due','Fecha objetivo',t.due,'date','required')}${field('hours','Horas de trabajo pendientes',t.hours,'number','required min="0.1" max="500" step="0.1"')}${select('status','Estado',['pendiente','en_curso','hecha'],t.status)}<label class="full">Notas<textarea name="note">${esc(t.note)}</textarea></label><button class="primary" type="submit">Guardar tarea</button></form>`);}
function affinity(origin=''){let cs=filtered();$('#content').innerHTML=`<div class="panel"><form id="recommend" class="form-grid"><label>Curso que ha realizado el alumno<select name="course">${opts(cs,'id','title',origin)}</select></label>${field('person','ID alumno (opcional: excluye su historial)')}<button class="primary" type="submit">Buscar continuidad</button></form><p class="mini">Afinidad de competencias por título, progresión y calendario. No envía mensajes ni matricula. Si falta horario, elegibilidad, cupo o fecha, la recomendación queda condicionada.</p></div><div id="recommendations"></div>`;}
async function showRecommendations(course,person=''){let {results}=await api('recommendations?course='+encodeURIComponent(course)+'&person='+encodeURIComponent(person));$('#recommendations').innerHTML=results.length?`<div class="grid2">${results.map(r=>`<div class="panel course-card"><div class="row">${badge(ename(r.course.entity))}${badge(r.course.program)}${badge('Condicionada','warn')}</div><h2>${esc(r.course.title)}</h2><p>${esc(r.course.code)} · ${r.course.hours} h · ${r.course.mode}</p><p>${esc(r.reasons.join('. '))}.</p><p class="mini">${esc(r.conditions.join('. '))}.</p>${calc({formula:r.formula,value:r.score,sources:[{source:r.course.source,locator:r.course.source_locator},{source:'Regla de afinidad propia',locator:'engine.py · FAMILIES y stage'}]})} ${button('Ver curso','course',r.course.id)}</div>`).join('')}</div>`:'<div class="empty">No hay una continuación compatible con los datos disponibles. Revisa el catálogo y las fechas.</div>';}
function rules(){const rows=[['Desempleo','Máximo 30 % de certificados válidos; situación al inicio. No hay mínimo.','convocatoria','art. 5.1.f y 5.2'],['Otros sectores','Pendiente de confirmar regla y denominador para el segundo plazo. No se aplica automáticamente el 30 % del primer plazo.','convocatoria','art. 5.3'],['CCAA de domicilio','A.2: 2–5 CCAA = 5 puntos; 6–9 = 12; ≥10 = 20. Cada CCAA exige ≥5 % del total certificado.','anexo_vi','A.2'],['Colectivos prioritarios','Mínimo del 50 %. Una persona en varios colectivos cuenta una vez por participación.','convocatoria','arts. 7 y 21.13'],['Finalización','General: ≥75 % de asistencia presencial o controles de aprendizaje en TF. Excepciones acreditadas de empleo, enfermedad o accidente: revisar el 25 %.','convocatoria','art. 21.9'],['Abandonos','No son automáticamente finalizados. Financiación limitada al 15 % de iniciados por acción, con condiciones y exclusión de sustituidos.','convocatoria','art. 21.10'],['Ámbito estatal','Es distinto del indicador A.2 de domicilios. Verificar centros, domicilio o centro de trabajo en más de una CCAA.','convocatoria','art. 21.1'],['Ejecución y agrupación','Ejecución <25 %: incumplimiento total. Miembro con ejecución <10 %: revisar admisibilidad de su actividad y costes.','anexo_vii','pp. 2–3']];$('#content').innerHTML=`<div class="panel">${table(['Control','Criterio','Fuente'],rows.map(r=>[r[0],r[1],source(r[2],r[3])]))}</div><div class="grid2"><div class="panel"><h2>Simular minoraciones</h2><form id="penalty" class="form-grid">${field('approved','Valoración técnica aprobada',78,'number','min="0" max="100" step="0.01" required')}${field('current','Valoración técnica final estimada',72,'number','min="0" max="100" step="0.01" required')}${field('priority','% colectivos prioritarios',50,'number','min="0" max="100" step="0.01" required')}${field('amount','Base justificada (€), opcional','','number','min="0" step="0.01"')}<button type="submit" class="primary">Calcular escenario</button></form><p class="mini">La base no es automáticamente la subvención concedida. No se suman causas de minoración. La VT completa exige A.1+A.2+A.3+B.1+B.2+C y sus evidencias; esta pantalla recibe la puntuación estimada.</p>${source('anexo_vii','pp. 4–5')}</div><div class="panel" id="penalty-result"><h2>Resultado del escenario</h2><p>Introduce valores para consultar la fórmula y la minoración orientativa.</p></div></div>`;}
function sources(){$('#content').innerHTML=`<div class="panel"><h2>Incidencias de contraste</h2>${S.issues.filter(i=>S.allocations.some(a=>a.id===i.scope&&(!entity||a.entity===entity)&&(!program||a.program===program))).map(i=>`<div class="issue"><div>${badge(i.severity,i.severity==='alta'?'bad':'warn')} <strong>${esc(i.title)}</strong></div><p>${esc(i.detail)}</p><div class="mini">${source(i.source,i.locator)}</div></div>`).join('')}</div><div class="panel"><h2>Documentos utilizados</h2><p>Copias de consulta incluidas con acceso protegido. La fecha de modificación no es la fecha de notificación. El enlace original permite comprobar versiones posteriores.</p>${table(['Documento','Copia consultada','Original','Modificado'],S.sources.map(s=>[esc(s.name),source(s.id),`<a href="${esc(s.url)}" target="_blank" rel="noopener">Abrir original</a>`,date(s.modified)]))}</div>`;}
function settings(){let cfg=S.settings;$('#content').innerHTML=`<div class="panel"><h2>API interna REST y Gestión GraphQL</h2><p>La sección Conexiones API permite vincular grupos, revisar campos y preparar consultas antes de aplicar datos. Las credenciales se mantienen en el servidor.</p>${button('Abrir conexiones','nav','integrations')}</div>${AUTH.role==='admin'?`<div class="panel"><h2>Supuestos de planificación</h2><form id="settings" class="form-grid">${[['conversion','Conversión de contactos a matrícula (0–1)'],['completion','Finalización esperada (0–1)'],['contact_minutes','Minutos por contacto'],['followup_minutes','Minutos de seguimiento por matrícula'],['hours_per_day','Horas formativas diarias'],['lead_days','Días de preparación'],['buffer_days','Margen antes del cierre (días)'],['cohort_size','Tamaño orientativo de grupo']].map(([k,l])=>field(k,l,cfg[k],'number','required min="0.01" step="0.01"')).join('')}<label class="full">Festivos (AAAA-MM-DD separados por coma)<input name="holidays" value="${esc(cfg.holidays.join(','))}"></label><button type="submit" class="primary">Guardar parámetros</button></form></div><div class="panel"><h2>Datos y trazabilidad</h2><div class="actions">${button('Importar matrículas JSON','import')}<a href="/api/export">Exportar copia de datos JSON</a>${button('Consultar auditoría','audit')}</div><p>La copia completa de base de datos y cuentas se realiza desde el servidor según el manual.</p></div>`:'<div class="panel">Los parámetros y las importaciones requieren administrador.</div>'}`;}
function explainDetail(m){dialog(`<h2>${esc(m.label)}</h2><div class="number">${num(m.value,2)} ${esc(m.unit)}</div><div class="formula">${esc(m.formula)}</div><p>Numerador: ${num(m.numerator,2)} · Denominador: ${num(m.denominator,2)} · Estado: ${esc(m.status)}</p><p>${source(m.source,m.locator)}</p><p>Actualización de registros: ${esc(m.updated_at||'Sin registros individuales')}.</p><h3>Registros del denominador</h3><p class="mini">${esc((m.denominator_ids||[]).join(', ')||'Sin registros')}</p><h3>Registros incluidos en el numerador (${m.record_ids.length})</h3><p class="mini">${esc(m.record_ids.join(', ')||'Ninguno / sin datos')}</p><h3>Registros excluidos y motivo</h3>${table(['Registro','Motivo'],(m.excluded_details||[]).map(x=>[esc(x.id),esc(x.reason)]))}${m.unknown_ids?.length?`<p class="banner">Datos desconocidos: ${esc(m.unknown_ids.join(', '))}. No se puede confirmar el cumplimiento.</p>`:''}${m.partner_sources?.length?'<h3>Cortes externos incluidos</h3>'+table(['Socio / informe','Corte','Numerador','Denominador','Origen'],m.partner_sources.map(r=>[esc(r.partner)+' · '+esc(r.id),date(r.as_of),num(r.numerator,2),num(r.denominator,2),esc(r.source)])):''}<h3>Fuentes de datos</h3><p>${esc((m.data_sources||[]).join(' · ')||'Programación; gestión pendiente')}</p>${(m.source_cells||[]).map(s=>`<p class="mini">${source(s.source,s.locator)}</p>`).join('')}<p class="mini">Las matrículas en curso, sin validar o sin certificación no forman parte del denominador certificado. Los indicadores de ejecución usan únicamente finalizados validados y los objetivos de la programación.</p>`);}
async function action(act,id){await integrationAction(act,id);await extraAction(act,id);if(act==='nav'){view=id;render();}if(act==='refresh')await refresh();if(act==='logout'){await api('logout',{});AUTH=await api('bootstrap');login();}if(act==='allocation')allocationDetail(id);if(act==='course')courseDetail(id);if(act==='explain')explainDetail(explains[+id]);if(act==='calc'){let x=calcs[+id];dialog(`<h2>Cálculo y fuente</h2><div class="formula">${esc(x.formula)}</div><pre>${esc(JSON.stringify(x.value,null,2))}</pre><p class="mini">${esc((x.records||[]).join(', '))}</p>${x.sources.map(s=>`<p class="mini">${source(s.source,s.locator)}</p>`).join('')}`);}if(act==='enrollment')enrollmentForm(id);if(act==='edit-enrollment')enrollmentForm('',id);if(act==='task')taskForm(id);if(act==='rec-origin'){$('#detail').close();view='affinity';entity='';program='';render();affinity(id);await showRecommendations(id);}if(act==='apply-plan'){await api('planning/apply',{revision:REV});toast('Borradores guardados. Solo los plazos confirmados generan tareas automáticas.');await refresh();}if(act==='manager'){let m=S.managers.find(x=>x.id===id);dialog(`<h2>Capacidad del gestor</h2><form id="manager" class="form-grid"><input name="id" type="hidden" value="${id}">${field('name','Nombre',m.name,'text','required')}${field('weekly_hours','Horas semanales disponibles',m.weekly_hours,'number','required min="0" max="60" step="0.5"')}${field('focus','Especialidad orientativa',m.focus)}<button type="submit" class="primary">Guardar</button></form>`);}if(act==='deadline')deadlineForm(S.allocations.find(a=>a.id===id)?.program||id);if(act==='import')dialog(`<h2>Importar matrículas</h2><form id="import"><p>Formato <code>sepe-import-v1</code>. La plantilla y el contrato se incluyen en el paquete. Se actualiza por ID estable; no se borran registros ausentes.</p><input type="file" name="file" accept="application/json,.json" required><p>Solo se aceptará el lote completo si pasa las validaciones.</p><button class="primary" type="submit">Validar e importar</button></form>`);if(act==='audit'){let a=await api('audit');dialog(`<h2>Auditoría · últimos 200 cambios</h2>${table(['Fecha','Usuario','Acción','Detalle'],a.rows.map(r=>[esc(r.time),esc(r.actor),esc(r.action),esc(r.detail)]))}`);}if(act==='password')dialog(`<h2>Cambiar contraseña</h2><form id="password">${field('old','Contraseña actual','','password','required autocomplete="current-password"')}${field('new','Nueva contraseña (mínimo 12 caracteres)','','password','required minlength="12" autocomplete="new-password"')}<button type="submit" class="primary">Cambiar contraseña</button></form>`);if(act==='group'){let g=S.groups.find(x=>x.id===id);dialog(`<h2>Ajustar calendario propuesto</h2><p>${esc(cname(g.course))}</p><form id="group" class="form-grid"><input name="id" type="hidden" value="${id}">${field('start','Inicio',g.start,'date','required')}${field('end','Fin',g.end,'date','required')}<label>Responsable<select name="owner">${opts(S.managers,'id','name',g.owner)}</select></label>${field('note','Motivo / validación de aulas y docentes',g.note,'text','required')}<button type="submit" class="primary">Guardar propuesta</button></form>`);}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(b)action(b.dataset.act,b.dataset.id).catch(e=>toast(e.message));});
document.addEventListener('change',e=>{if(e.target.id==='entity'){entity=e.target.value;render();}if(e.target.id==='program'){program=e.target.value;render();}if(e.target.id==='search'){query=e.target.value;courses();}});
document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));try{if(await integrationSubmit(f,d))return;await extraSubmit(f,d);if(f.getAttribute('id')==='login'){AUTH=await api('login',d);await refresh();return;}if(f.getAttribute('id')==='recommend'){await showRecommendations(d.course,d.person);return;}if(f.getAttribute('id')==='penalty'){let r=await api('penalties',d);$('#penalty-result').innerHTML=`<h2>Simulación, no liquidación</h2><p>Desviación VT: ${num(r.technical_deviation,2)} puntos.</p><p>Minoración VT: ${num(r.technical.min,2)}–${num(r.technical.max,2)} % · ${esc(r.technical.status)}</p><p>Minoración por colectivos: ${num(r.priority.min,2)}–${num(r.priority.max,2)} %.</p><p>Importes separados: ${num(r.technical.amount_min,2)}–${num(r.technical.amount_max,2)} € y ${num(r.priority.amount_min,2)}–${num(r.priority.amount_max,2)} €.</p><div class="formula">${esc(r.formula)}</div><p>${esc(r.note)}</p>${source(r.source,r.locator)}`;return;}if(f.getAttribute('id')==='enrollment'){if(!d.id)delete d.id;d.validated=f.validated.checked;d.certified_valid=f.certified_valid.checked;d.priority=d.priority==='Desconocido'?null:d.priority==='Sí';d.progress=d.progress===''?null:Number(d.progress);await api('enrollment',{revision:REV,enrollment:d});}if(f.getAttribute('id')==='task'){d.hours=+d.hours;await api('task',{revision:REV,task:d});}if(f.getAttribute('id')==='settings'){let o={};for(let[k,v]of Object.entries(d))o[k]=k==='holidays'?v.split(',').map(x=>x.trim()).filter(Boolean):+v;await api('settings',{revision:REV,settings:o});}if(f.getAttribute('id')==='manager'){d.weekly_hours=+d.weekly_hours;await api('manager',{revision:REV,manager:d});}if(f.getAttribute('id')==='deadline')await api('deadline',{revision:REV,...d});if(f.getAttribute('id')==='group')await api('group',{revision:REV,group:d});if(f.getAttribute('id')==='import'){let file=f.file.files[0];if(file.size>8000000)throw Error('Archivo demasiado grande (máximo 8 MB)');await api('import',{revision:REV,data:JSON.parse(await file.text())});}if(f.getAttribute('id')==='password')await api('password',d);$('#detail').close();toast('Guardado correctamente');await refresh();}catch(err){if(f.getAttribute('id')==='login')$('#login-error').textContent=err.message;else toast(err.message);}});
function deadlines(){const ds=S.programs.filter(p=>!program||p.id===program).map(p=>DASH.deadlines[p.id]);$('#content').innerHTML=`<div class="banner">Las fechas originales se conservan. Una fecha provisional permite simular calendarios, pero solo un plazo confirmado genera tareas automáticas de captación. Las fechas en revisión bloquean propuestas.</div><div class="panel">${table(['Expediente','Fin de ejecución','Días restantes','Estado','Alertas',''],ds.map(x=>[x.program+'<br>'+esc(S.programs.find(p=>p.id===x.program).name),date(x.date),num(x.days_left),badge(x.status,x.status==='confirmada'?'good':'warn'),(x.expired?badge('Vencido','bad')+' ':'' )+`${x.courses_after_deadline.length} cursos posteriores · ${x.invalid_course_dates.length} fechas incoherentes · ${x.saved_after_deadline.length} propuestas fuera de plazo`,button('Ver fechas y fuente','deadline-view',x.program)]))}</div>`;}
function deadlineView(pid){let x=DASH.deadlines[pid];dialog(`<h2>Fechas de ${pid}</h2><p>Fecha utilizada: <strong>${date(x.date)}</strong> · ${badge(x.status)} · ${num(x.days_left)} días restantes.</p><p>${esc(x.evidence)}</p><p>Notificación registrada: ${date(x.notification_date)}.</p><h3>Fechas originales de programación</h3>${table(['Entidad','Fecha','Fuente'],x.originals.map(o=>[ename(o.entity),date(o.date),source(o.source,o.cell)]))}<h3>Cursos y propuestas afectados</h3>${table(['Referencia','Motivo'],[...x.courses_after_deadline.map(id=>[esc(cname(id)),'Fin posterior al límite']),...x.invalid_course_dates.map(id=>[esc(cname(id)),'Fin anterior al inicio']),...x.saved_after_deadline.map(id=>[esc(id),'Propuesta guardada fuera del plazo'])])}<h3>Historial de fechas anteriores</h3>${table(['Fin anterior','Estado','Evidencia','Cambio'],x.history.map(h=>[date(h.date),esc(h.status),esc(h.evidence),esc(h.changed_at)+' · '+esc(h.actor)]))}${AUTH.role==='admin'?button('Registrar o revisar fecha','deadline-form',pid,'primary'):''}<p class="mini">Días restantes = fecha utilizada − fecha actual de Canarias. El plazo se introduce desde la notificación o prórroga: no se deduce automáticamente de la firma del documento.</p>`);}
function deadlineForm(pid){let x=DASH.deadlines[pid];dialog(`<h2>Fecha límite del expediente</h2><p>El cambio afecta a ambos centros que participan en ${pid}. Se conserva el valor original y se revisan los calendarios guardados.</p><form id="deadline" class="form-grid"><input type="hidden" name="program" value="${pid}">${field('deadline','Fin de ejecución',x.date,'date','required')}${select('status','Estado',['provisional','confirmada','en_revision'],x.status)}${field('notification_date','Fecha de notificación (si consta)',x.notification_date,'date')}${field('evidence','Documento y página / motivo de revisión',x.evidence,'text','required')}<button type="submit" class="primary">Guardar fecha y evidencia</button></form>`);}
function consortiumView(){let ps=S.programs.filter(p=>!program||p.id===program);$('#content').innerHTML=`<div class="banner">Vista de toda la agrupación, independiente del filtro de empresa local. Solo se suman los cortes activos validados de socios externos. Akacenter y Juan Pablo se obtienen de sus matrículas, evitando añadirlos otra vez como socios.</div><div class="toolbar">${AUTH.role==='admin'?button('Añadir socio','partner')+button('Introducir resultados','partner-report')+button('Importar CSV de socios','partner-import'):''}<a href="/api/partner-template.csv">Descargar plantilla CSV</a></div><div class="panel"><h2>Entidades registradas</h2>${table(['ID / entidad','NIF','Expedientes',''],S.partners.map(x=>[esc(x.id)+'<br>'+esc(x.name),esc(x.nif),x.programs.join(', '),AUTH.role==='admin'?button('Editar','partner',x.id):'']))}</div>${ps.map(p=>{let g=DASH.programs[p.id],v=g.coverage;return `<div class="panel"><div class="toolbar"><h2>${p.id} · ${esc(p.name)}</h2>${badge(g.complete?'Cobertura declarada':'Cobertura parcial',g.complete?'good':'warn')}</div><p>${esc(g.coverage_note)}</p><p>${v.validated_reports} cortes externos validados de ${v.registered_partners} socios registrados. Corte local: ${date(v.cutoff)}. ${v.same_dates?'Fechas de corte alineadas.':'Fechas de corte pendientes o distintas.'}</p>${!v.roster_verified?'<p class="warning-text">Composición completa de la agrupación sin confirmar.</p>':''}${v.missing_partners.length?`<p>Faltan resultados validados de: ${esc(v.missing_partners.map(id=>S.partners.find(p=>p.id===id).name).join(', '))}.</p>`:''}<div class="cards">${g.metrics.filter((m,i)=>[0,2,3,4].includes(i)).map(metric).join('')}</div>${table(['Socio','Corte activo','Certificados','Validación','Documento / localizador',''],v.reports.map(r=>[esc(S.partners.find(x=>x.id===r.partner).name),date(r.as_of),num(r.certified),badge(r.verified?'Validado':'Pendiente',r.verified?'good':'warn'),esc(r.source),AUTH.role==='admin'?button('Editar corte','partner-report',r.id):'']))}<div class="toolbar">${AUTH.role==='admin'?button('Composición y cierre local','coverage',p.id):''}${button('Ver todos los cortes','partner-history',p.id)}</div></div>`}).join('')}`;}
function partnerForm(id=''){let x=S.partners.find(x=>x.id===id)||{name:'',nif:'',programs:[]};dialog(`<h2>Socio externo de la agrupación</h2><form id="partner" class="form-grid"><input type="hidden" name="id" value="${esc(id)}">${field('name','Razón social',x.name,'text','required')}${field('nif','NIF',x.nif,'text','required minlength="8" maxlength="12"')}<div class="full"><p>Expedientes en los que participa</p>${S.programs.map(p=>`<label class="check"><input type="checkbox" name="programs" value="${p.id}" ${x.programs.includes(p.id)?'checked':''}>${p.id} · ${esc(p.name)}</label>`).join('')}</div><button type="submit" class="primary">Guardar socio</button><p class="full mini">El NIF identifica la entidad entre planes. No registres aquí Akacenter ni Juan Pablo. Cambiar la composición exige volver a confirmarla con su documento.</p></form>`);}
const partnerFields=[['certified','Certificados válidos'],['unemployed','Desempleados entre certificados'],['priority','Prioritarios entre certificados'],['own_sector','Ocupados sector propio certificados'],['other_sector','Ocupados otros sectores certificados'],['finalized','Finalizados validados'],['target','Objetivo de participantes del socio'],['final_hours','Horas participante finalizadas'],['target_hours','Objetivo de horas participante'],['certified_hours','Horas participante certificadas'],['physical_hours','Horas participante certificadas presenciales']];
function partnerReportForm(id=''){if(!S.partners.length){toast('Registra primero los socios y sus expedientes.');return;}let r=S.partner_reports.find(r=>r.id===id)||{as_of:new Date().toISOString().slice(0,10),verified:false,geo:{},active:true};dialog(`<h2>Resultados del socio a una fecha de corte</h2><form id="partner-report" class="form-grid"><input type="hidden" name="id" value="${esc(id)}"><label>Socio<select name="partner">${opts(S.partners,'id','name',r.partner)}</select></label><label>Expediente<select name="program">${opts(S.programs,'id','id',r.program||program)}</select></label>${field('as_of','Fecha de corte de los datos',r.as_of,'date','required')}${field('source','Documento y hoja/celda o página',r.source,'text','required')}<p class="full">Introduce solo los resultados de esta entidad en este expediente. No incluyas totales de toda la agrupación. Un campo vacío significa desconocido; escribe 0 cuando conste que es cero. Para validar el corte, certificados válidos es obligatorio.</p>${partnerFields.map(([k,l])=>field(k,l,r[k],'number',`min="0" max="100000000" step="${k.includes('hours')?'0.01':'1'}" `)).join('')}<h3 class="full">CCAA de domicilio de certificados válidos</h3>${ccaa.map((x,i)=>field('geo_'+i,x,r.geo?.[x],'number','min="0" step="1"')).join('')}<label class="check full"><input type="checkbox" name="verified" ${r.verified?'checked':''}>He validado el resumen y su documento de origen</label><label class="check full"><input type="checkbox" name="active" ${r.active!==false?'checked':''}>Utilizar como corte activo (sustituye al anterior de este socio y expediente)</label><p class="full mini">No se suman cortes mensuales o históricos. Sin desglose completo por CCAA, el indicador territorial queda incompleto. Los agregados no permiten detectar personas duplicadas entre entidades.</p><button type="submit" class="primary">Guardar resultados</button></form>`);}
function coverageForm(pid){let p=S.programs.find(p=>p.id===pid),c=p.local_close||{};dialog(`<h2>Composición y corte local de ${pid}</h2><form id="coverage" class="form-grid"><input type="hidden" name="program" value="${pid}"><label class="check full"><input type="checkbox" name="roster_verified" ${p.group_roster_verified?'checked':''}>He registrado todos los socios externos que participan en el expediente</label>${field('roster_evidence','Documento de composición y página',p.group_roster_evidence)}${field('as_of','Corte común de Akacenter y Juan Pablo',c.as_of,'date')}${field('local_evidence','Informe que acredita cierre local completo',c.evidence)}<p class="full">Confirmar el corte declara que las matrículas locales están completas a esa fecha, incluso si el resultado es cero. Cualquier cambio o importación de matrículas anula esta declaración. Los socios deben aportar cortes de la misma fecha.</p><button type="submit" class="primary">Guardar declaración</button></form>`);}
async function extraAction(act,id){if(act==='deadline-view')deadlineView(id);if(act==='deadline-form')deadlineForm(id);if(act==='partner')partnerForm(id);if(act==='partner-report')partnerReportForm(id);if(act==='coverage')coverageForm(id);if(act==='partner-import')dialog(`<h2>Importar resultados externos</h2><form id="partner-import"><p>Descarga la plantilla CSV y consulta el mapa de columnas en docs/AGRUPACION_Y_FECHAS.txt. Una fila por socio y expediente. Los IDs de socio se consultan en la tabla de entidades.</p><input type="file" name="file" accept=".csv,text/csv" required><p>Solo se aplica si todo el lote es válido. No sumar cierres históricos ni totales que ya incluyan estas dos empresas.</p><button type="submit" class="primary">Validar e importar</button></form>`);if(act==='partner-history')dialog(`<h2>Historial de resultados de ${id}</h2>${table(['ID','Socio','Corte','Estado','Fuente'],S.partner_reports.filter(r=>r.program===id).map(r=>[esc(r.id),esc(S.partners.find(p=>p.id===r.partner).name),date(r.as_of),badge(r.active?'Activo':'Histórico'),esc(r.source)]))}<p>Las correcciones de un mismo ID se conservan en su historial y la auditoría.</p>`);}
async function extraSubmit(f,d){let id=f.getAttribute('id');if(id==='partner'){d.programs=new FormData(f).getAll('programs');await api('partner',{revision:REV,partner:d});}if(id==='partner-report'){if(!d.id)delete d.id;d.verified=f.elements.namedItem('verified').checked;d.active=f.elements.namedItem('active').checked;d.geo={};for(const [k]of partnerFields)d[k]=d[k]===''?null:Number(d[k]);for(let i=0;i<ccaa.length;i++){let v=d['geo_'+i];if(v!=='')d.geo[ccaa[i]]=Number(v);delete d['geo_'+i];}await api('partner-report',{revision:REV,report:d});}if(id==='coverage'){d.roster_verified=f.elements.namedItem('roster_verified').checked;await api('group-coverage',{revision:REV,...d});}if(id==='partner-import'){let file=f.elements.namedItem('file').files[0];if(file.size>8000000)throw Error('Máximo 8 MB');await api('partner-import',{revision:REV,csv:await file.text()});}}

(async()=>{try{AUTH=await api('bootstrap');if(AUTH.user)await refresh();else login();}catch(e){toast(e.message);}})();
